typeql:
match
$u isa user;
$t isa tweet;
posts (author: $u, content: $t);
reduce $tweet_count = count($t) groupby $u;
sort $tweet_count desc;
limit 3;
fetch { "screen_name": $u.screen_name };

match
$me isa me, has screen_name "neo4j";
$user isa user;
amplifies (amplifier: $me, amplified_user: $user);
$user has followers $followers;
sort $followers desc;
limit 5;
fetch {
  "name": $user.name,
  "followers": $followers
};

match
$u isa user, has following $f;
$m isa me, has screen_name "neo4j";
follows (follower: $u, followed: $m);
sort $f asc;
limit 3;
fetch {
  "name": $u.name,
  "screen_name": $u.screen_name,
  "following": $f
};

match
$t isa tweet, has favorites $f;
$f > 200;
$h isa hashtag;
tags (tagged_tweet: $t, tag: $h);
reduce $count = count($t) groupby $h;
sort $count desc;
limit 3;
fetch { "hashtag": $h.hashtag_name, "tag_count": $count };

match
$t isa tweet, has favorites $fav;
$l isa link;
contains (containing_tweet: $t, contained_link: $l);
sort $fav desc;
limit 5;
fetch {
  "tweet_text": $t.text,
  "favorites": $fav,
  "link_url": $l.link_url
};

match
$u isa user, has screen_name "neo4j";
posts (author: $u, content: $t);
tags (tagged_tweet: $t, tag: $h);
reduce $usage_count = count($t) groupby $h;
sort $usage_count desc;
limit 3;
fetch {
  "hashtag": $h.hashtag_name,
  "usage_count": $usage_count
};

match
$u isa user, has location $loc;
posts (author: $u, content: $t);
$t isa tweet;
reduce $num_statuses = count($t) groupby $u, $loc;
sort $num_statuses desc;
limit 5;
fetch {
  "location": $loc,
  "num_statuses": $num_statuses
};

match
$u isa user, has screen_name "neo4j";
$t isa tweet, has favorites $f;
mentions (source_tweet: $t, mentioned_user: $u);
$f > 100;
sort $f desc;
limit 3;
fetch {
  "text": $t.text,
  "favorites": $f,
  "created_at": $t.created_at
};

match
$t isa tweet, has favorites $f;
using (tweet_content: $t, platform: $s);
$s isa source;
sort $f desc;
limit 5;
fetch {
  "source_name": $s.source_name,
  "favorites": $f
};

match
$u isa user, has profile_image_url $piu;
$m isa me, has screen_name "neo4j";
posts (author: $u, content: $t);
mentions (source_tweet: $t, mentioned_user: $m);
$t has created_at $ca;
sort $ca desc;
limit 3;
fetch {
  "profile_image_url": $piu
};

match
$me isa me, has screen_name "neo4j";
$rel isa interacts_with (interactor: $me, target: $user);
reduce $count = count($rel) groupby $user;
sort $count desc;
limit 3;
fetch { "userName": $user.name, "interactionCount": $count };

match
$me isa me, has screen_name "neo4j";
posts (author: $me, content: $tweet);
retweets (retweeting_tweet: $tweet, original_tweet: $retweet);
posts (author: $user, content: $retweet);
reduce $retweet_count = count($retweet) groupby $user;
sort $retweet_count desc;
limit 3;
fetch { "user": $user.screen_name, "retweet_count": $retweet_count };

match
$t isa tweet, has favorites $f;
contains (containing_tweet: $t, contained_link: $l);
sort $f desc;
limit 3;
fetch {
  "url": $l.link_url
};

match
$me isa me, has screen_name "neo4j";
posts (author: $me, content: $tweet);
retweets (retweeting_tweet: $tweet, original_tweet: $rt);
tags (tagged_tweet: $rt, tag: $hashtag);
$hashtag has hashtag_name $hn;
reduce $count = count groupby $hashtag, $hn;
sort $count desc;
limit 3;
fetch { "hashtag": $hn, "count": $count };

match
$t isa tweet, has favorites $f, has text $text;
reply_to (replying_tweet: $t, original_tweet: $other);
$other isa tweet;
$f > 50;
sort $f desc;
limit 5;
fetch {
  "tweet_text": $text
};

match
$me isa me, has screen_name "neo4j";
interacts_with (interactor: $me, target: $user);
$user has location $loc;
reduce $count = count($user) groupby $loc;
sort $count desc;
limit 3;
fetch { "location": $loc, "interaction_count": $count };

match
$me isa me, has screen_name "neo4j";
follows (follower: $me, followed: $user);
posts (author: $user, content: $tweet);
tags (tagged_tweet: $tweet, tag: $hashtag);
$hashtag has hashtag_name "specificHashtag";
reduce $tweet_count = count($tweet) groupby $user;
sort $tweet_count desc;
limit 3;
fetch { "userName": $user.screen_name, "tweetCount": $tweet_count };

match
$u isa user, has screen_name "neo4j";
posts (author: $u, content: $t);
using (tweet_content: $t, platform: $s);
$s isa source, has source_name "Buffer";
$t has favorites $f;
sort $f desc;
limit 5;
fetch {
  "text": $t.text,
  "created_at": $t.created_at,
  "favorites": $f
};

match
$u isa user, has betweenness $b;
sort $b desc;
limit 5;
fetch {
  "screen_name": $u.screen_name,
  "betweenness": $b
};

match
$u isa user, has screen_name "neo4j";
posts (author: $u, content: $t);
retweets (original_tweet: $t, retweeting_tweet: $rt);
reduce $count = count($rt) groupby $t;
match $count > 100;
sort $count desc;
limit 3;
fetch { "text": $t.text, "retweet_count": $count };

match
$u isa user, has screen_name $sn;
$m isa me, has screen_name "neo4j";
$t isa tweet;
posts (author: $u, content: $t);
mentions (source_tweet: $t, mentioned_user: $m);
reduce $count = count($t) groupby $u, $sn;
sort $count desc;
limit 3;
fetch { "user": $sn, "mention_count": $count };

match
$me isa me, has screen_name "neo4j", has location $loc;
$user isa user, has screen_name $sn, has followers $f;
$user has location $loc;
follows (follower: $me, followed: $user);
sort $f desc;
limit 5;
fetch {
  "screen_name": $sn,
  "followers": $f
};

match
$me isa me, has screen_name "neo4j";
posts (author: $me, content: $tweet);
retweets (original_tweet: $tweet, retweeting_tweet: $rt);
posts (author: $user, content: $rt);
$user has followers $f;
sort $f desc;
limit 3;
fetch {
  "profile_image_url": $user.profile_image_url
};

match
  $me isa me, has name "Neo4j";
  $s isa similar_to (source_user: $u, similar_user: $me), has score $score;
  $u has name $name;
sort $score desc;
limit 5;
fetch { "name": $name, "similarity": $score };

match
$me isa me, has screen_name "neo4j";
follows (follower: $me, followed: $user);
$tweet isa tweet;
posts (author: $user, content: $tweet);
reduce $tweet_count = count($tweet) groupby $user;
match $tweet_count > 500;
sort $tweet_count desc;
limit 3;
fetch { "screen_name": $user.screen_name, "tweet_count": $tweet_count };

match
$me isa me, has name "Neo4j";
follows (follower: $me, followed: $user);
$user has followers $f;
sort $f desc;
