  "favorites": $f
};

match
$t isa tweet, has favorites $f;
sort $f desc;
limit 3;
fetch {
  "text": $t.text,
  "favorites": $f
};

match
$u isa user, has name $name, has followers $f;
$m isa me, has screen_name "neo4j";
follows (follower: $u, followed: $m);
$f > 500;
fetch {
  "userName": $name,
  "followersCount": $f
};

match
$u isa user, has screen_name "neo4j", has location $loc;
$loc != "Graphs Are Everywhere";
posts (author: $u, content: $t);
$t has created_at $ca;
sort $ca desc;
limit 5;
fetch {
  "tweet": $t.text,
  "posted_at": $ca
};

match
$me isa me, has screen_name "neo4j";
amplifies (amplifier: $me, amplified_user: $user);
$user has name $name;
reduce $count = count groupby $user, $name;
sort $count desc;
limit 3;
fetch { "name": $name, "amplification_count": $count };

match
$me isa me;
posts (author: $me, content: $tweet);
contains (containing_tweet: $tweet, contained_link: $link);
$tweet has created_at $ca;
sort $ca asc;
limit 3;
fetch {
  "tweet": { $tweet.* }
};

match
$u isa user, has followers $f;
$f == 663;
sort $f desc;
limit 5;
fetch {
  "screen_name": $u.screen_name,
  "name": $u.name,
  "followers": $f
};

match
$u isa user, has screen_name "neo4j";
posts (author: $u, content: $t);
$t has created_at $ca;
$ca >= 2021-01-01T00:00:00;
fetch {
  "created_at": $ca,
  "text": $t.text,
  "tweet_id": $t.tweet_id,
  "favorites": $t.favorites
};

match
$neo4j isa user, has screen_name "neo4j";
$me isa me;
$u isa user, has screen_name $sn, has followers $f, has following $fg;
follows (follower: $u, followed: $neo4j);
follows (follower: $u, followed: $me);
sort $f desc;
limit 5;
fetch {
  "screen_name": $sn,
  "followers": $f,
  "following": $fg
};

match
$me isa me;
posts (author: $me, content: $tweet);
mentions (source_tweet: $tweet, mentioned_user: $user);
$user isa user;
$tweet has created_at $ca;
sort $ca asc;
limit 3;
fetch {
  "created_at": $tweet.created_at,
  "tweet_id": $tweet.tweet_id,
  "text": $tweet.text,
  "favorites": $tweet.favorites
};

match
$u isa user, has screen_name "neo4j";
mentions (source_tweet: $t, mentioned_user: $u);
tags (tagged_tweet: $t, tag: $h);
reduce $tweetCount = count($t) groupby $h;
match $tweetCount > 5;
fetch { "hashtag": $h.hashtag_name, "tweetCount": $tweetCount };

match
$me isa me, has screen_name "neo4j", has betweenness $mb;
similar_to ($me, $user);
$user isa user, has betweenness $ub;
let $diff = abs($ub - $mb);
sort $diff asc;
limit 5;
fetch {
  "screen_name": $user.screen_name,
  "betweenness": $ub
};

match
$u isa user, has screen_name "neo4j";
posts (author: $u, content: $t);
$t has favorites $f;
$f > 300;
$t has created_at $ca;
sort $ca asc;
limit 3;
