};

match
$u isa user, has screen_name "neo4j";
posts (author: $u, content: $t);
mentions (source_tweet: $t, mentioned_user: $mentionedUser);
select $t, $mentionedUser;
distinct;
reduce $mentionedCount = count($mentionedUser) groupby $t;
match $mentionedCount >= 2;
fetch {
  "tweet_text": $t.text,
  "tweet_date": $t.created_at,
  "mentionedCount": $mentionedCount
};

