using (tweet_content: $retweet, platform: $source);
$source has source_name $sn;
reduce $count = count groupby $source, $sn;
sort $count desc;
limit 3;
fetch { "source_name": $sn, "retweet_count": $count };

match
$u isa user;
$t isa tweet;
$h isa hashtag, has hashtag_name "education";
posts (author: $u, content: $t);
tags (tagged_tweet: $t, tag: $h);
reduce $count = count($t) groupby $u;
sort $count desc;
limit 3;
fetch { "user": $u.screen_name, "tweet_count": $count };

match
$me isa me, has screen_name "neo4j";
posts (author: $me, content: $reply);
reply_to (replying_tweet: $reply, original_tweet: $original);
$original has favorites $f;
sort $f desc;
limit 5;
fetch {
  "original_tweet": $original.text,
  "created_at": $original.created_at,
  "favorites": $f
};

match
$t isa tweet, has text $text, has favorites $fav;
$h isa hashtag, has hashtag_name "education";
tags (tagged_tweet: $t, tag: $h);
$rt isa tweet;
retweets (original_tweet: $t, retweeting_tweet: $rt);
reduce $retweet_count = count($rt), $fav_val = max($fav) groupby $t;
sort $retweet_count desc, $fav_val desc;
limit 3;
fetch { "tweet": $t.text, "favorites": $fav_val, "retweet_count": $retweet_count };

match
