with fun follows_count($u: user) -> integer:
  match follows (follower: $u, followed: $f);
  return count;
with fun mentions_count($u: user) -> integer:
  match mentions (source_tweet: $t, mentioned_user: $u);
  return count;
with fun retweets_count($u: user) -> integer:
  match posts (author: $u, content: $t); retweets (original_tweet: $t, retweeting_tweet: $rt);
  return count;
match
  $u isa user;
let $fc = follows_count($u);
let $mc = mentions_count($u);
let $rc = retweets_count($u);
let $total = $fc + $mc + $rc;
sort $total desc;
limit 5;
fetch { "user": $u.screen_name, "total_interactions": $total };

