$user has followers $f;
sort $f desc;
limit 5;
fetch {
  "screen_name": $sn,
  "followers": $f
};

match
$t isa tweet, has created_at $ca;
$u isa user, has screen_name "neo4j";
mentions (source_tweet: $t, mentioned_user: $u);
tags (tagged_tweet: $t, tag: $h);
$h isa hashtag;
$ca >= 2021-01-01T00:00:00;
$ca < 2022-01-01T00:00:00;
sort $ca;
limit 3;
fetch {
  "tweet": $t.text,
  "created_at": $ca
};

match
$u isa user, has screen_name "neo4j";
posts (author: $u, content: $t);
contains (containing_tweet: $t, contained_link: $l);
$l has link_url $url;
$url like "https://.*";
$t has favorites $fav;
sort $fav desc;
limit 5;
fetch {
  "text": $t.text,
  "created_at": $t.created_at,
  "url": $url
};

match
$u isa user, has following $f, has screen_name $sn;
$t isa tweet;
$m isa me, has screen_name "neo4j";
posts (author: $u, content: $t);
mentions (source_tweet: $t, mentioned_user: $m);
$f > 20000;
sort $f desc;
limit 5;
fetch {
  "screen_name": $sn,
  "following": $f
};

match
$me isa me, has screen_name "neo4j";
follows (follower: $me, followed: $user);
try { posts (author: $user, content: $tweet); };
reduce $count = count($tweet) groupby $user;
sort $count desc;
limit 3;
fetch {
  "screen_name": $user.screen_name,
  "tweet_count": $count
};

match
$source isa source;
using (tweet_content: $t, platform: $source);
reduce $usage_count = count($t) groupby $source;
sort $usage_count desc;
limit 3;
fetch {
  "source": $source.source_name,
  "usage_count": $usage_count
};

match
$u isa user, has followers $f, has location $l;
$f > 10000;
$l == "Graphs Are Everywhere";
fetch {
  "screen_name": $u.screen_name,
  "name": $u.name,
  "followers": $f,
  "location": $l
};

match
$t isa tweet, has favorites $f;
sort $f desc;
limit 5;
fetch {
  "text": $t.text,
  "favorites": $f
};

match
$u isa user, has following $f, has screen_name $sn;
sort $f desc;
limit 3;
fetch {
  "screen_name": $sn,
  "following": $f
};

match
$neo4j isa me, has screen_name "neo4j";
$user isa user, has location "Graphs Are Everywhere";
follows (follower: $user, followed: $neo4j);
limit 3;
fetch {
  "screen_name": $user.screen_name,
  "name": $user.name,
  "location": $user.location
};

match
$u isa user, has betweenness $b, has name $n;
sort $b desc;
limit 5;
fetch {
  "name": $n
};

match
$u isa user, has following $fg, has followers $fr;
$fg > 5000;
$fr < 10000;
limit 5;
fetch {
  "screen_name": $u.screen_name,
  "following": $fg,
  "followers": $fr
};

match
$t isa tweet, has created_at $ca;
contains (containing_tweet: $t, contained_link: $l);
$l isa link;
$ca >= 2021-01-01T00:00:00;
$ca < 2022-01-01T00:00:00;
limit 3;
fetch {
  "tweet": $t.text
};

match
$me isa me;
$rel isa similar_to (source_user: $me, similar_user: $user);
$rel has score $s;
sort $s desc;
limit 5;
fetch {
  "screen_name": $user.screen_name,
  "score": $s
};

match
$u isa user, has location "Graphs Are Everywhere";
posts (author: $u, content: $t);
tags (tagged_tweet: $t, tag: $h);
reduce $usage_count = count($t) groupby $h;
sort $usage_count desc;
limit 3;
fetch { "hashtag": $h.hashtag_name, "usage_count": $usage_count };

match
$neo4j isa me, has screen_name "neo4j";
mentions (source_tweet: $tweet, mentioned_user: $neo4j);
using (tweet_content: $tweet, platform: $source);
$source has source_name $sn;
reduce $tweet_count = count($tweet) groupby $source, $sn;
sort $tweet_count desc;
limit 3;
fetch { "source": $sn, "tweet_count": $tweet_count };

match
$u isa user;
$rel isa interacts_with (interactor: $u, target: $other);
$other isa user;
reduce $interactions = count($rel) groupby $u;
sort $interactions desc;
limit 5;
fetch {
  "user": $u.screen_name,
  "interactions": $interactions
};

match
$me isa me, has screen_name "neo4j";
posts (author: $me, content: $originalTweet);
retweets (original_tweet: $originalTweet, retweeting_tweet: $retweet);
$retweet has favorites $f;
sort $f desc;
limit 3;
fetch {
  "retweetText": $retweet.text,
  "retweetDate": $retweet.created_at,
  "retweetFavorites": $f
};

match
$me isa me, has screen_name "neo4j";
$user isa user;
amplifies (amplifier: $user, amplified_user: $me);
reduce $count = count groupby $user;
sort $count desc;
limit 3;
fetch { "screen_name": $user.screen_name, "amplification_count": $count };

match
$me isa me, has screen_name "neo4j";
posts (author: $me, content: $tweet);
retweets (retweeting_tweet: $tweet, original_tweet: $retweet);
mentions (source_tweet: $retweet, mentioned_user: $user);
$retweet has created_at $ca;
sort $ca desc;
limit 5;
fetch {
  "tweet_text": $retweet.text,
  "tweet_id": $retweet.tweet_id,
  "created_at": $ca
};

match
$me isa me, has screen_name "neo4j";
posts (author: $me, content: $tweet);
retweets (retweeting_tweet: $tweet, original_tweet: $original);
mentions (source_tweet: $original, mentioned_user: $user);
reduce $count = count groupby $user;
sort $count desc;
limit 3;
fetch { "screen_name": $user.screen_name, "retweet_count": $count };

match
$u isa user, has screen_name $sn, has name $n;
$t isa tweet;
$h isa hashtag, has hashtag_name "education";
posts (author: $u, content: $t);
tags (tagged_tweet: $t, tag: $h);
limit 3;
fetch {
  "screen_name": $sn,
  "name": $n
};

with fun reply_count($t: tweet) -> integer:
    match reply_to (original_tweet: $t, replying_tweet: $r);
    return count;
match
    $u isa user, has screen_name "neo4j";
    posts (author: $u, content: $t);
let $count = reply_count($t);
sort $count desc;
limit 3;
fetch { "tweet_id": $t.id_str, "tweet_text": $t.text, "reply_count": $count };

match
$t isa tweet, has favorites $f;
$u isa user, has screen_name "neo4j";
mentions (source_tweet: $t, mentioned_user: $u);
$l isa link;
contains (containing_tweet: $t, contained_link: $l);
sort $f desc;
limit 5;
fetch {
  "tweet_text": $t.text,
  "link_url": $l.link_url
};

match
$t isa tweet;
retweets (original_tweet: $t, retweeting_tweet: $rt);
reduce $rt_count = count($rt) groupby $t;
match
$rt_count > 100;
tags (tagged_tweet: $t, tag: $h);
reduce $count = count($t) groupby $h;
sort $count desc;
limit 3;
fetch { "hashtag": $h.hashtag_name, "count": $count };

match
$t isa tweet, has created_at $ca;
$l isa link, has link_url "https://twitter.com/i/web/status/13718150212657479";
contains (containing_tweet: $t, contained_link: $l);
$ca >= 2021-03-01T00:00:00Z;
$ca < 2021-04-01T00:00:00Z;
fetch {
  "tweet": { $t.* }
};

match
$me isa me, has screen_name "neo4j";
interacts_with (interactor: $me, target: $user);
$user has followers $f, has name $n;
sort $f desc;
limit 3;
fetch {
  "name": $n,
  "followers": $f
};

match
